import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"【Глава 4】 Обеспечение безопасности","description":"","frontmatter":{},"headers":[],"relativePath":"ru/document/level-0/ch04-security.md","filePath":"ru/document/level-0/ch04-security.md","lastUpdated":1783169976000}`),a={name:`ru/document/level-0/ch04-security.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="【глава-4】-обеспечение-безопасности" tabindex="-1">【Глава 4】 Обеспечение безопасности <a class="header-anchor" href="#【глава-4】-обеспечение-безопасности" aria-label="Permalink to “【Глава 4】 Обеспечение безопасности”">​</a></h1><h2 id="_4-1-зачем-нужна-безопасность" tabindex="-1">4.1 Зачем нужна безопасность? <a class="header-anchor" href="#_4-1-зачем-нужна-безопасность" aria-label="Permalink to “4.1 Зачем нужна безопасность?”">​</a></h2><p>Безопасность Linux-серверов — это обширная и сложная тема. Бесчисленные веб-сайты, приложения, сервисы и даже критически важная инфраструктура построены на базе Linux. За всем этим стоят огромные деньги и коммерческие интересы, что, естественно, привлекает злоумышленников. В то же время надёжная работа этих сервисов крайне важна, поэтому любые серьёзные уязвимости недопустимы. Именно поэтому множество специалистов по безопасности изо дня в день ведут борьбу на передовой, обеспечивая стабильную работу цифрового мира, к которому мы все привыкли.</p><p>Теперь, когда у вас есть собственный VPS-сервер, и вы собираетесь открыть на нём порты для перенаправления трафика, вы фактически оказываетесь на передовой этой борьбы и подвергаетесь тем же рискам. В то же время, новички, не обладающие достаточными знаниями и информацией, склонны впадать в крайности: либо они считают, что им ничего не угрожает, либо же, наоборот, впадают в паранойю.</p><ul><li><p>Первым я бы посоветовал не относиться к безопасности легкомысленно и изучить этот вопрос более подробно, чтобы потом не пришлось кусать локти.</p></li><li><p>Вторым я бы посоветовал не паниковать. Ваш сервер вряд ли представляет собой лакомую цель для серьёзных злоумышленников, поэтому вам достаточно базовых мер защиты от автоматических сканеров и ботов, о которых мы и поговорим в этой главе.</p></li></ul><h2 id="_4-2-какие-именно-риски-существуют" tabindex="-1">4.2 Какие именно риски существуют? <a class="header-anchor" href="#_4-2-какие-именно-риски-существуют" aria-label="Permalink to “4.2 Какие именно риски существуют?”">​</a></h2><p>Как мы уже говорили в главе про удалённое подключение, для доступа к вашему VPS достаточно знать четыре вещи: <strong>IP-адрес</strong>, <strong>порт</strong>, <strong>имя пользователя</strong> и <strong>пароль</strong>. Очевидно, что эти четыре элемента нужно защищать в первую очередь. Давайте разберём каждый из них:</p><ol><li><p><strong>IP-адрес</strong>: злоумышленники могут сканировать целые диапазоны IP-адресов в поисках уязвимых серверов. Ваш IP-адрес — это публичная информация, которую невозможно скрыть.</p></li><li><p><strong>Порт</strong>: если вы используете настройки по умолчанию, то порт SSH равен <code>22</code>.</p></li><li><p><strong>Имя пользователя</strong>: если вы используете настройки по умолчанию, то имя пользователя — <code>root</code>.</p></li><li><p><strong>Пароль</strong>: пароль не имеет значения по умолчанию. Он либо генерируется автоматически при создании VPS, либо задаётся вами. Таким образом, если вы не меняли настройки сервера, то три из четырёх элементов уже известны злоумышленникам, и вся безопасность вашего сервера держится на одном только пароле. Возможны следующие варианты:</p><ul><li><p>Вы используете автоматически сгенерированный пароль из панели управления VPS. Такие пароли обычно состоят из случайного набора символов (букв в разных регистрах, цифр и спецсимволов) и достаточно надёжны.</p></li><li><p>Вы установили простой пароль, например, <code>123456</code>. Взломать такой сервер не составит труда.</p></li><li><p>Вы установили сложный пароль, который используете где-то ещё. Это тоже небезопасно. Злоумышленники используют специальные программы, которые перебирают миллионы ранее скомпрометированных паролей из утечек данных.</p></li></ul></li><li><p>Важно понимать, что никакой хакер не будет лично подбирать ваш пароль. Все атаки выполняются автоматически с помощью специальных скриптов, которые работают круглосуточно. Пока вы спите, ваш сервер может подвергаться атакам.</p><p>Если пароль будет подобран, злоумышленники получат полный доступ к вашему серверу (права пользователя <code>root</code>), смогут установить на него вредоносное ПО и использовать его в своих целях (например, для майнинга криптовалюты, рассылки спама, фишинговых атак, организации торрент-трекера, размещения публичных узлов для доступа к даркнету и т.д.). При этом злоумышленники могут действовать очень скрытно, и вы даже не заметите, что ваш сервер взломан, пока не получите уведомление от хостинг-провайдера о блокировке вашего аккаунта или, что ещё хуже, повестку в суд.</p></li><li><p>Не забывайте, что при покупке VPS вы, скорее всего, указывали свои реальные платёжные данные. А при посещении сайтов и использовании социальных сетей ваш IP-адрес также сохраняется. Всё это может быть использовано против вас. <strong>Поэтому, если на вашем сервере произойдёт что-то противозаконное, отвечать за это придётся вам.</strong></p></li></ol><h2 id="_4-3-какие-меры-безопасности-нужно-предпринять" tabindex="-1">4.3 Какие меры безопасности нужно предпринять? <a class="header-anchor" href="#_4-3-какие-меры-безопасности-нужно-предпринять" aria-label="Permalink to “4.3 Какие меры безопасности нужно предпринять?”">​</a></h2><p>Исходя из всего вышесказанного, нам нужно защитить <strong>порт</strong>, <strong>имя пользователя</strong> и <strong>пароль</strong>, чтобы снизить риск взлома. Для этого необходимо:</p><ol><li>Изменить порт SSH на <strong>нестандартный</strong> (отличный от 22) (см. раздел 4.4).</li><li>Создать <strong>нового пользователя</strong> (не <code>root</code>) и <strong>запретить удалённое подключение по SSH</strong> для пользователя <code>root</code> (см. разделы 4.5 и 4.6).</li><li>Настроить <strong>аутентификацию по SSH-ключам</strong> и <strong>запретить аутентификацию по паролю</strong> (см. раздел 4.7).</li></ol><p>Выполняйте эти действия по порядку, чтобы не оказаться случайно заблокированным на своём же сервере.</p><h2 id="_4-4-изменение-порта-ssh" tabindex="-1">4.4 Изменение порта SSH <a class="header-anchor" href="#_4-4-изменение-порта-ssh" aria-label="Permalink to “4.4 Изменение порта SSH”">​</a></h2><p>Давайте решим проблему с портом SSH, который по умолчанию равен <code>22</code> (обратите внимание: у некоторых хостинг-провайдеров порт SSH по умолчанию уже отличается от 22. В этом случае вы можете пропустить этот шаг, но можете и изменить порт ещё раз, следуя инструкциям ниже).</p><ol><li><p>Базовые команды Linux:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Номер</th><th style="text-align:left;">Команда</th><th style="text-align:left;">Описание</th></tr></thead><tbody><tr><td style="text-align:center;"><code>cmd-03</code></td><td style="text-align:left;"><code>nano</code></td><td style="text-align:left;">Текстовый редактор</td></tr><tr><td style="text-align:center;"><code>cmd-04</code></td><td style="text-align:left;"><code>systemctl restart</code></td><td style="text-align:left;">Перезапуск службы</td></tr></tbody></table></li><li><p>Важные файлы конфигурации Linux:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Номер</th><th style="text-align:left;">Путь к файлу</th><th style="text-align:left;">Описание</th></tr></thead><tbody><tr><td style="text-align:left;"><code>conf-01</code></td><td style="text-align:left;"><code>/etc/ssh/sshd_config</code></td><td style="text-align:left;">Настройки SSH-сервера</td></tr></tbody></table></li><li><p>Первое, что нужно сделать, — это открыть файл настроек SSH-сервера (<code>/etc/ssh/sshd_config</code>) в текстовом редакторе <code>nano</code>. В Windows вы бы просто нашли этот файл и дважды кликнули по нему. А как это сделать в Linux? Если вы внимательно читали предыдущие разделы, то наверняка уже догадались! Правильно, нужно выполнить команду:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">nano</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> /etc/ssh/sshd_config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>После открытия файла вы увидите интерфейс редактора <code>nano</code>. Обратите внимание на нижнюю часть экрана, где перечислены основные горячие клавиши (на скриншоте ниже выделены красной рамкой). Не нужно ничего заучивать, всё необходимое всегда перед глазами!</p><p><img src="/assets/ch04-img01-nano-ui.B4Aenfjz.png" alt="Интерфейс nano" width="835" height="640"></p></li></ol><ol start="5"><li><p>Второе, что нужно сделать, — это найти строку, начинающуюся с <code>Port</code>, и изменить номер порта. Число после <code>Port</code> — это номер порта SSH. Рекомендуется использовать число в диапазоне от <code>1024</code> до <code>65535</code> (в этой статье мы будем использовать порт <code>9753</code>). Как это сделать, используя горячие клавиши <code>nano</code>? Вы уже наверняка догадались!</p><ul><li>Нажмите <code>Ctrl+W</code>, чтобы открыть поиск, введите <code>Port 22</code> и нажмите Enter.</li><li>Замените <code>22</code> на <code>9753</code>.</li><li>Примечание: если в начале строки стоит символ <code>#</code>, значит, эта строка закомментирована и не будет применяться. Вы можете либо раскомментировать её (удалив <code>#</code>), либо добавить новую строку без <code>#</code> в конце файла, как показано на скриншоте.</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Использование порта <code>9753</code> в этой статье делает его менее безопасным, поскольку злоумышленники могут начать сканировать этот порт в первую очередь. Кроме того, этот порт может быть заблокирован некоторыми провайдерами. Поэтому настоятельно рекомендуем использовать другой порт. У вас в распоряжении более 60 тысяч портов, так что выбрать есть из чего.</p></div></li></ol><ol start="6"><li>Третье, что нужно сделать, — это сохранить изменения и выйти из редактора. <ul><li>Как вы уже могли заметить, для сохранения файла используется не <code>Ctrl+S</code>, как в большинстве программ.</li><li>Горячие клавиши: <code>Ctrl+O</code> — сохранить, <code>Ctrl+X</code> — выйти.</li></ul></li></ol><ul><li><p>Добавьте новое правило в брандмауэр, чтобы открыть новый порт SSH. В противном случае, после перезагрузки инстанса, подключение по SSH будет недоступно.</p></li><li><p><strong>Пример для Ubuntu с использованием <code>ufw</code>:</strong></p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">sudo</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> ufw</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> allow</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> 9753/tcp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ul><ol start="7"><li><p>И последнее, что нужно сделать, — это перезапустить SSH-сервер, чтобы изменения вступили в силу.</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">systemctl</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> restart</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> ssh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Затем можно попробовать открыть новую сессию в SSH-клиенте и проверить подключение. Если возникнут проблемы, можно изменить конфигурацию в старой SSH-сессии (открытые SSH-соединения не будут разорваны при перезапуске службы SSHD).</p></li><li><p>Весь процесс показан на гифке ниже:</p><p><img src="/assets/ch04-img02-sshd-conf-full.Dv8kUzC-.gif" alt="Изменение порта SSH" width="839" height="644"></p></li><li><p>Изменение настроек PuTTY</p><p>Теперь, когда вы изменили порт SSH, вам нужно указать новый порт (<code>9753</code>) в настройках PuTTY. Вы ведь помните, где это делается? (Если нет, вернитесь и перечитайте предыдущие разделы!)</p></li></ol><h2 id="_4-5-создание-нового-пользователя" tabindex="-1">4.5 Создание нового пользователя <a class="header-anchor" href="#_4-5-создание-нового-пользователя" aria-label="Permalink to “4.5 Создание нового пользователя”">​</a></h2><p>Перейдём ко второму шагу — избавлению от пользователя <code>root</code>.</p><p>Прежде всего, нужно понимать, что пользователь <code>root</code> в Linux — это не просто администратор. Это корень системы, её основа, верховный правитель. Если безопасность учётной записи <code>root</code> будет нарушена, под угрозой окажется вся система.</p><ol><li><p>Базовые команды Linux:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Номер</th><th style="text-align:left;">Команда</th><th style="text-align:left;">Описание</th></tr></thead><tbody><tr><td style="text-align:center;"><code>cmd-05</code></td><td style="text-align:left;"><code>adduser</code></td><td style="text-align:left;">Добавление нового пользователя</td></tr><tr><td style="text-align:center;"><code>cmd-06</code></td><td style="text-align:left;"><code>apt install</code></td><td style="text-align:left;">Установка программного обеспечения</td></tr><tr><td style="text-align:center;"><code>cmd-07</code></td><td style="text-align:left;"><code>visudo</code></td><td style="text-align:left;">Редактор файла sudoers</td></tr></tbody></table></li><li><p>Первое, что нужно сделать, — это создать нового пользователя и установить для него пароль. Имя пользователя может быть любым, в этой статье мы будем использовать имя <code>vpsadmin</code>.</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">adduser</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> vpsadmin</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Следуйте инструкциям на экране. Обязательно укажите пароль для нового пользователя (и не удивляйтесь, что при вводе пароля символы не отображаются). Далее система может запросить дополнительную информацию о пользователе. Можете пропустить эти пункты, нажав Enter.</p><p><img src="/assets/ch04-img03-adduser.B0VGcN0p.png" alt="Создание нового пользователя" width="835" height="640"></p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Использование имени пользователя <code>vpsadmin</code> в этой статье делает его менее безопасным, поскольку злоумышленники могут начать перебирать пароли для этого имени в первую очередь. Поэтому, как и в случае с портом, настоятельно рекомендуем использовать другое имя пользователя.</p></div></li><li><p>Весь процесс показан на гифке ниже:</p><p><img src="/assets/ch04-img04-adduser-full.DgDkjVtm.gif" alt="Создание нового пользователя" width="839" height="644"></p></li><li><p>Второе, что нужно сделать, — это установить пакет <code>sudo</code> (<code>sudo</code> позволяет обычным пользователям временно получать права суперпользователя <code>root</code>, чтобы выполнять задачи, требующие повышенных привилегий).</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">apt</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> update</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;"> &amp;&amp; </span><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">apt</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> install</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> sudo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Вы, наверное, заметили, что эта строка содержит две команды. Первая команда, <code>apt update</code>, уже знакома вам — она обновляет информацию о доступных пакетах. Вторая команда, <code>apt install</code>, используется для установки программного обеспечения. В данном случае мы обновляем информацию о пакетах и устанавливаем последнюю версию <code>sudo</code>. Символы <code>&amp;&amp;</code> используются для объединения нескольких команд в одну строку.</p></li><li><p>Третье, что нужно сделать, — это добавить пользователя <code>vpsadmin</code> в группу <code>sudo</code>, чтобы он мог использовать команду <code>sudo</code>.</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">visudo</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Добавьте следующую строку в раздел <code>User Privilege Specification</code>: <code>vpsadmin ALL=(ALL) NOPASSWD: ALL</code>.</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Обратите внимание на опцию <code>NOPASSWD</code>. Она означает, что пользователю <code>vpsadmin</code> не нужно будет вводить пароль при использовании команды <code>sudo</code>. <strong>Это противоречит общепринятым рекомендациям по безопасности.</strong> Однако я рекомендую сделать именно так, потому что многие новички используют учётную запись <code>root</code> именно потому, что им не нужно каждый раз вводить пароль. Я считаю, что <strong>риски от использования учётной записи <code>root</code> гораздо выше</strong>, чем риски от использования <code>sudo</code> без пароля.</p><p>Если вы всё же хотите, чтобы при каждом использовании <code>sudo</code> запрашивался пароль, используйте следующую строку: <code>vpsadmin ALL=(ALL:ALL) ALL</code>.</p></div></li><li><p>Весь процесс показан на гифке ниже:</p><p><img src="/assets/ch04-img05-sudo-full.DeKisL39.gif" alt="Настройка sudo" width="839" height="644"></p></li></ol><h2 id="_4-6-запрет-удаленного-подключения-по-ssh-для-пользователя-root" tabindex="-1">4.6 Запрет удалённого подключения по SSH для пользователя root <a class="header-anchor" href="#_4-6-запрет-удаленного-подключения-по-ssh-для-пользователя-root" aria-label="Permalink to “4.6 Запрет удалённого подключения по SSH для пользователя root”">​</a></h2><ol><li><p>Вы уже немного освоились в Linux, поэтому попробуйте сами догадаться, что нужно сделать в первую очередь. Правильно, нужно снова открыть файл настроек SSH-сервера (<code>/etc/ssh/sshd_config</code>) в редакторе <code>nano</code>. Не помните, как это сделать? Вернитесь и перечитайте предыдущие разделы! ... Правильный ответ:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">nano</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> /etc/ssh/sshd_config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Найдите строку <code>PermitRootLogin Yes</code> и замените <code>yes</code> на <code>no</code>. Помните, как это сделать? ... Правильный ответ:</p><ul><li>Нажмите <code>Ctrl+W</code>, чтобы открыть поиск, введите <code>PermitRootLogin</code> и нажмите Enter.</li><li>Замените <code>yes</code> на <code>no</code>.</li></ul></li><li><p>Сохраните изменения и выйдите из редактора. Помните, как это сделать? ... Правильный ответ:</p><ul><li><code>Ctrl+O</code> — сохранить, <code>Enter</code> — подтвердить сохранение.</li><li><code>Ctrl+X</code> — выйти.</li></ul></li><li><p>Перезапустите SSH-сервер, чтобы изменения вступили в силу. Помните... Ладно, вот правильный ответ:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">systemctl</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> restart</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> ssh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Весь процесс показан на гифке ниже:</p><p><img src="/assets/ch04-img06-ssh-no-root-full.DZeR7uks.gif" alt="Запрет удалённого подключения для root" width="839" height="644"></p></li><li><p>Теперь при попытке подключения по SSH с помощью PuTTY под пользователем <code>root</code> вы получите ошибку. Используйте имя пользователя <code>vpsadmin</code> для подключения. Для удобства вы можете указать <code>vpsadmin</code> в качестве имени пользователя по умолчанию в настройках PuTTY (не забудьте сохранить сеанс!).</p><p><img src="/assets/ch04-img07-putty-default-user.D6pt-VE-.png" alt="Имя пользователя по умолчанию в PuTTY" width="466" height="448"></p></li></ol><h2 id="_4-7-настроика-аутентификации-по-ssh-ключам-и-запрет-аутентификации-по-паролю" tabindex="-1">4.7 Настройка аутентификации по SSH-ключам и запрет аутентификации по паролю <a class="header-anchor" href="#_4-7-настроика-аутентификации-по-ssh-ключам-и-запрет-аутентификации-по-паролю" aria-label="Permalink to “4.7 Настройка аутентификации по SSH-ключам и запрет аутентификации по паролю”">​</a></h2><p>Перейдём к третьему шагу — защите от подбора пароля.</p><p>Как мы уже говорили, хакеры не будут подбирать ваш пароль вручную. Они используют специальные программы и базы данных с миллионами скомпрометированных паролей. Если вы не используете случайно сгенерированный пароль достаточной длины (например, с помощью менеджера паролей, такого как 1Password или Keychain в macOS), ваш пароль могут подобрать.</p><p>Конечно, можно использовать длинный и сложный пароль, но такой пароль сложно запомнить и легко ввести неправильно. Чтобы решить эту проблему, можно вообще отказаться от аутентификации по паролю и использовать более безопасный способ — аутентификацию по SSH-ключам.</p><p><strong>Аутентификация по SSH-ключам</strong> основана на использовании пары связанных ключей — <strong>публичного</strong> и <strong>приватного</strong>. Публичный ключ помещается на сервер, а приватный ключ хранится у вас на компьютере. При подключении по SSH клиент предъявляет серверу публичный ключ, а сервер, в свою очередь, шифрует с помощью него случайное сообщение и отправляет клиенту. Клиент расшифровывает сообщение с помощью приватного ключа и отправляет результат обратно на сервер. Если результат совпадает с ожидаемым, аутентификация считается успешной (таким образом, вам не нужно запоминать и вводить сложный пароль, достаточно лишь защитить свой приватный ключ от кражи).</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>В этой статье мы рассмотрим использование <strong>RSA-ключей</strong>, поскольку они поддерживаются практически всеми SSH-клиентами и до сих пор считаются достаточно надёжными. Однако это не единственный вариант.</p><p>Существуют и другие алгоритмы:</p><ul><li><strong>DSA</strong>: этот алгоритм считается небезопасным, поэтому использовать его не рекомендуется.</li><li><strong>ECDSA</strong>: этот алгоритм обеспечивает высокий уровень безопасности при меньшем размере ключа, однако существуют подозрения, что в нём есть уязвимости, которые могут быть использованы АНБ. Поэтому, если вы храните на своём сервере что-то действительно важное, лучше не использовать этот алгоритм.</li><li><strong>Ed25519</strong>: этот алгоритм похож на ECDSA, но считается более безопасным, поскольку его код открыт и доступен для изучения.</li></ul><p>Поэтому, если ваше оборудование и программное обеспечение поддерживают этот алгоритм, рекомендуется использовать именно его.</p></div><p>Итак, давайте настроим аутентификацию по SSH-ключам.</p><ol><li><p>Запустите программу <strong>PuTTYgen</strong> (генератор ключей PuTTY). Она находится в меню «Пуск» --&gt; «Все программы» --&gt; «PuTTY (64-bit)» --&gt; «PuTTYgen».</p><ol><li><p>Нажмите кнопку <strong>Generate</strong>, чтобы сгенерировать ключи (поводите курсором мыши по пустому пространству окна, чтобы добавить энтропии).</p><p><img src="/assets/ch04-img08-puttygen-save.CHw98Rml.png" alt="Генерация ключей" width="493" height="477"></p></li></ol><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>На скриншоте показан пример генерации 2048-битного RSA-ключа. Однако для достижения уровня безопасности, сопоставимого с 256-битным ключом ECDSA/Ed25519, вам нужно сгенерировать 3072-битный RSA-ключ (т.е. ввести значение <code>3072</code> в поле «Number of bits in a generated key»). ::: 2. Вы можете установить пароль для защиты приватного ключа. 3. Нажмите кнопку <strong>Save public key</strong>, чтобы сохранить публичный ключ в файл <code>id_rsa.pub</code>. 4. Нажмите кнопку <strong>Save private key</strong>, чтобы сохранить приватный ключ в файл <code>id_rsa</code> (приватные ключи PuTTY имеют расширение <code>.ppk</code>). 5. <strong>Важно!</strong> Скопируйте содержимое поля, выделенного красной рамкой (не забудьте прокрутить текст до конца!), и сохраните его в файл <code>authorized_keys</code>. (Если вы будете использовать для этого VSCode, файл будет сохранён с расширением <code>.txt</code> — <code>authorized_keys.txt</code>. Это нормально, позже мы переименуем файл).</p><p><img src="/assets/ch04-img09-puttygen-save-keys.NM1Wm7kW.png" alt="Сохранение ключей" width="1024" height="768"></p></div></li><li><p>Скопируйте публичный ключ на VPS в домашний каталог пользователя <code>vpsadmin</code>.</p><ol><li><p>Для этого используйте программу <strong>WinSCP</strong>, которую мы установили ранее.</p></li><li><p>Скачайте и установите WinSCP с <a href="https://winscp.net/eng/index.php" target="_blank" rel="noreferrer">официального сайта</a>. При первом запуске программа предложит импортировать настройки из PuTTY. Согласитесь на импорт.</p><p><img src="/assets/ch04-img10-winscp-import-session.sXjUnOBu.png" alt="Импорт настроек из PuTTY" width="612" height="470"></p></li><li><p>Если вам не предложили импортировать настройки или вы уже настроили WinSCP ранее, настройте подключение к VPS, как показано на скриншоте ниже.</p><p><img src="/assets/ch04-img11-winscp-ui.AN7pET93.png" alt="Настройки подключения в WinSCP" width="1090" height="700"></p></li><li><p>В левой части окна WinSCP отображаются файлы и папки на вашем компьютере, а в правой — на VPS. Перейдите в папку с сохранёнными ключами на вашем компьютере.</p></li><li><p>В правой части окна (VPS) по умолчанию открыт каталог <code>/home/vpsadmin/</code>. Нажмите кнопку «Show hidden files» (скрытые файлы), чтобы отобразить скрытые файлы и папки.</p><p><img src="/assets/ch04-img12-winscp-locations.XArMgNVV.png" alt="Локальные и удалённые папки" width="1088" height="684"></p></li><li><p>щёлкните правой кнопкой мыши в правой части окна (VPS) и создайте новую папку с именем <code>.ssh</code> (обратите внимание на точку в начале имени).</p><p><img src="/assets/ch04-img13-winscp-newfolder-key.CM1OfBQF.png" alt="Создание папки для ключей на VPS" width="1088" height="684"></p></li><li><p>Скопируйте файл <code>authorized_keys</code> в папку <code>.ssh</code>.</p><p><img src="/assets/ch04-img14-winscp-upload-key.BygTVpGm.png" alt="Копирование authorized_keys" width="1088" height="684"></p></li><li><p>При копировании файла <code>authorized_keys.txt</code> переименуйте его в <code>authorized_keys</code> (удалите расширение <code>.txt</code>).</p><p><img src="/assets/ch04-img15-winscp-rename-key.8iQ3gLs7.png" alt="Удаление расширения файла" width="1088" height="684"></p></li><li><p>Весь процесс показан на гифке ниже:</p><p><img src="/assets/ch04-img16-winscp-full.B_z2QlO-.gif" alt="Работа с WinSCP" width="1093" height="691"></p></li></ol></li><li><p>Настройте SSH-сервер на использование ключей и отключите аутентификацию по паролю.</p><ol><li><p>Базовые команды Linux:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Номер</th><th style="text-align:left;">Команда</th><th style="text-align:left;">Описание</th></tr></thead><tbody><tr><td style="text-align:center;"><code>cmd-08</code></td><td style="text-align:left;"><code>sudo</code></td><td style="text-align:left;">Выполнение команды от имени root</td></tr><tr><td style="text-align:center;"><code>cmd-09</code></td><td style="text-align:left;"><code>chmod</code></td><td style="text-align:left;">Изменение прав доступа к файлам и папкам</td></tr></tbody></table></li><li><p>Подключитесь к VPS по SSH (PuTTY).</p></li><li><p>Измените права доступа к файлу <code>authorized_keys</code> на <code>600</code> (только владелец может читать и записывать файл).</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">chmod</span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;"> 600</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> ~/.ssh/authorized_keys</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Откройте файл настроек SSH. Мы уже делали это раньше, но теперь мы работаем не под пользователем <code>root</code>, а под пользователем <code>vpsadmin</code>. У этого пользователя нет прав на редактирование системных файлов, поэтому нужно использовать команду <code>sudo</code>:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">sudo</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> nano</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> /etc/ssh/sshd_config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Найдите (<code>Ctrl+W</code>) строку <code>PasswordAuthentication</code> и измените значение на <code>no</code>.</p></li><li><p>Найдите (<code>Ctrl+W</code>) строку <code>PubkeyAuthentication</code> и измените значение на <code>yes</code>. Сохраните изменения (<code>Ctrl+O</code>) и выйдите из редактора (<code>Ctrl+X</code>).</p></li><li><p>Перезапустите SSH-сервер (не забудьте, что теперь вам нужно использовать команду <code>sudo</code>):</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">sudo</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> systemctl</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> restart</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> ssh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Весь процесс показан на гифке ниже:</p><p><img src="/assets/ch04-img17-rsa-login-full.CZytVZwr.gif" alt="Включение аутентификации по ключам и отключение аутентификации по паролю" width="840" height="645"></p></li></ol></li><li><p>Теперь, когда на сервере настроен публичный ключ, нужно указать PuTTY путь к приватному ключу (не забудьте сохранить сеанс!).</p><p><img src="/assets/ch04-img18-putty-privatekey-location.DW84vHHi.png" alt="Путь к приватному ключу в PuTTY" width="466" height="448"></p></li><li><p>Готово! Теперь у вас настроена аутентификация по SSH-ключам, а аутентификация по паролю отключена. Кроме того, вы сохранили имя пользователя и путь к приватному ключу в сеансе PuTTY. Теперь для подключения к VPS достаточно будет выбрать сохранённый сеанс <code>VPS-SERVER</code> и нажать кнопку «Open».</p><p>Если вы установили пароль для защиты приватного ключа, вам нужно будет ввести его при подключении, как показано на скриншоте ниже:</p><p><img src="/assets/ch04-img19-putty-privatekey-passphrase.DQfUeTjA.png" alt="Парольная фраза для приватного ключа" width="835" height="640"></p></li><li><p>Не забудьте настроить аутентификацию по ключам и в WinSCP. В противном случае вы не сможете подключаться к серверу для передачи файлов:</p><p><img src="/assets/ch04-img20-winscp-privatekey-location.LtQ_87aZ.png" alt="Путь к приватному ключу в WinSCP" width="1422" height="688"></p></li></ol><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Теперь для подключения к вашему серверу по SSH требуется авторизация по ключам. Мы рассмотрели настройку PuTTY и WinSCP, но существует множество других программ, которые также используют SSH. Настройте их самостоятельно при необходимости.</p></div><h2 id="_4-8-ваш-прогресс" tabindex="-1">4.8 Ваш прогресс <a class="header-anchor" href="#_4-8-ваш-прогресс" aria-label="Permalink to “4.8 Ваш прогресс”">​</a></h2><p>На этом этапе ваш VPS защищён базовыми мерами безопасности. Конечно, это не панацея, но большинство автоматизированных атак вам уже не страшны!</p><p>Теперь у нас есть надёжный фундамент, и в следующей главе мы можем приступить к установке и настройке необходимых компонентов Xray (а именно, веб-сервера и SSL-сертификата).</p><blockquote><p>⬛⬛⬛⬛⬜⬜⬜⬜ 50%</p></blockquote>`,38)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};